UPDATE dailyRecords SET cycleId = 270002 WHERE cycleId = 270003;
UPDATE dailyRecords SET cycleId = 330001 WHERE cycleId = 330002;

-- 重複サイクルを削除
DELETE FROM monthlyCycles WHERE id IN (270003, 330002);

-- UNIQUE制約を追加
ALTER TABLE `monthlyCycles` ADD CONSTRAINT `monthlyCycles_userId_cycleStartDate_unique` UNIQUE(`userId`,`cycleStartDate`);

